body:
POST /api/commands HTTP/1.1
Host: localhost:4000
Content-Type: application/json
Cookie: sempkm_session=8a1e…

{
  "commands": [{
    "command": "object.create",
    "params": {
      "type": "Note",
      "slug": "isometric-drawing",
      "properties": {
        "dcterms:title": "Isometric drawing",
        "sempkm:body": "Axonometric, not perspective."
      }
    },
    "slot": "n1"
  }]
}

BEGIN                              -- RDF4J transaction

INSERT DATA {
  GRAPH <urn:sempkm:event:0f3c9a71> {
    <urn:sempkm:event:0f3c9a71>
      a                       sempkm:Event ;
      sempkm:timestamp        "2026-08-14T20:41:07+00:00"^^xsd:dateTime ;
      sempkm:operation        "object.create" ;
      sempkm:affected         <urn:sempkm:obj:isometric-drawing> ;
      sempkm:description      "Created Note 'Isometric drawing'" ;
      sempkm:performedBy      <urn:sempkm:user:8a1e…> ;
      sempkm:performedByRole  "owner" .

    <urn:sempkm:obj:isometric-drawing>
      a               model:Note ;
      dcterms:title   "Isometric drawing" .
  }
} ;

INSERT DATA {
  GRAPH <urn:sempkm:current> {
    <urn:sempkm:obj:isometric-drawing>
      a               model:Note ;
      dcterms:title   "Isometric drawing" .
  }
} ;

COMMIT

POST https://peer.example/inbox
Signature: keyId="https://me.example/webid#key",
           algorithm="rsa-sha256", signature="pQr…"

{
  "patch": {
    "insert": [
      ["urn:sempkm:obj:isometric-drawing",
       "http://purl.org/dc/terms/title",
       "Isometric drawing"]
    ],
    "delete": []
  },
  "graph":  "urn:sempkm:shared:4c2a…",
  "origin": "https://me.example"
}

[] a sh:ValidationReport ;
   sh:conforms false ;
   sh:result [
     a                        sh:ValidationResult ;
     sh:focusNode             <urn:sempkm:obj:isometric-drawing> ;
     sh:resultPath            model:project ;
     sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
     sh:resultSeverity        sh:Warning ;
     sh:resultMessage         "A Note should belong to a Project."
   ] .

SELECT ?p ?o WHERE {
  GRAPH <urn:sempkm:current> {          # ← scope_to_current_graph()
    <urn:sempkm:obj:isometric-drawing> ?p ?o .
  }
}

─── 3 rows ───────────────────────────────────────
rdf:type        model:Note
dcterms:title   "Isometric drawing"
sempkm:body     "Axonometric, not perspective."

{
  "urn:sempkm:obj:isometric-drawing": "Isometric drawing",
  "urn:sempkm:model:basic-pkm:Note":   "Note",
  "urn:sempkm:user:8a1e…":             "james"
}

render_block(
  "browser/object_tab.html",
  block = "tab_body",              # ← htmx asked for a fragment
  obj   = {
    "iri":    "urn:sempkm:obj:isometric-drawing",
    "label":  "Isometric drawing",
    "type":   {"iri": "…:Note", "label": "Note"},
    "fields": [ … from the SHACL NodeShape … ],
  },
)

{
  "commands": [
    {"command":"object.create",
     "params":{"type":"Note","slug":"daily-2026-08-14",
               "properties":{"dcterms:title":"2026-08-14"}},
     "slot":"n1"},

    {"command":"edge.create",
     "params":{"subject":"@n1","predicate":"model:mentions",
               "object":"urn:sempkm:obj:isometric-drawing"}}
  ]
}

{
  "command": "object.create",
  "params": {
    "type": "Project",
    "slug": "q3-planning",
    "properties": {
      "dcterms:title": "Q3 Planning",
      "model:status":  "In progress",
      "model:due":     "2026-09-30"
    }
  }
}

# Notion select → model:status
# Notion date   → xsd:date literal

@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix model:   <urn:sempkm:model:basic-pkm:> .

<urn:sempkm:obj:axonometry>
    a              model:Concept ;
    dcterms:title  "Axonometry" ;
    model:relates  <urn:sempkm:obj:isometric-drawing> .

# → 3 triples → 1 Operation → 1 event

{
  "@id": "model:NoteTable",
  "@type": "sempkm:ViewSpec",
  "sempkm:targetClass": {"@id": "model:Note"},
  "sempkm:renderer": "table",
  "sempkm:column": [
    {"sempkm:path":"dcterms:title", "sempkm:label":"Title"},
    {"sempkm:path":"model:project", "sempkm:label":"Project"},
    {"sempkm:path":"dcterms:modified","sempkm:label":"Updated"}
  ]
}

{
  "renderer": "table",
  "page": 1, "per_page": 50, "total": 182,
  "columns": ["Title", "Project", "Updated"],
  "rows": [
    ["Isometric drawing", "Diagramming", "2026-08-14"],
    ["Axonometry",        "Diagramming", "2026-08-12"]
  ]
}

SELECT ?class ?parent ?label WHERE {
  GRAPH <urn:sempkm:model:basic-pkm:ontology> {
    ?class a owl:Class .
    OPTIONAL { ?class rdfs:subClassOf ?parent }
    OPTIONAL { ?class rdfs:label      ?label  }
  }
}

─── 4 rows ───────────────────────────────
model:Note     owl:Thing   "Note"
model:Project  owl:Thing   "Project"
model:Concept  owl:Thing   "Concept"
model:Person   owl:Thing   "Person"

INSERT DATA {
  GRAPH <urn:sempkm:inferred> {
    <urn:sempkm:obj:isometric-drawing> a model:Thing .
    <urn:sempkm:obj:diagramming>
        model:contains <urn:sempkm:obj:isometric-drawing> .
  }
}

# rule: rdfs:subClassOf  → type propagation
# rule: owl:inverseOf    → model:project ⁻¹ = model:contains

PREFIX search: <http://www.openrdf.org/contrib/lucenesail#>

SELECT ?subject ?score WHERE {
  ?subject search:matches [
    search:query  "axonometric~" ;
    search:score  ?score
  ] .
}
ORDER BY DESC(?score)
LIMIT 20

-- "notes about drawing that have no project"

SELECT ?note ?title WHERE {
  GRAPH <urn:sempkm:current> {
    ?note a model:Note ;
          dcterms:title ?title .
    FILTER(CONTAINS(LCASE(?title), "drawing"))
    FILTER NOT EXISTS { ?note model:project ?p }
  }
}

-- validate_query(): model:Note ✓  dcterms:title ✓  model:project ✓

GET /canvas/neighbours?iri=urn:sempkm:obj:isometric-drawing&hops=1

{
  "nodes": [
    {"iri":"…:isometric-drawing", "label":"Isometric drawing", "type":"Note"},
    {"iri":"…:diagramming",       "label":"Diagramming",       "type":"Project"},
    {"iri":"…:axonometry",        "label":"Axonometry",        "type":"Concept"}
  ],
  "edges": [
    {"s":"…:isometric-drawing","p":"model:project","o":"…:diagramming"},
    {"s":"…:axonometry","p":"model:relates","o":"…:isometric-drawing"}
  ]
}

test("creating a note writes exactly one event", async ({ page }) => {
  await page.goto("/browser");
  await page.click("[data-new-object='Note']");
  await page.fill("[name='dcterms:title']", "Isometric drawing");
  await page.click("[data-save]");

  await expect(page.locator(".object-head h1"))
    .toHaveText("Isometric drawing");

  const events = await api.get("/browser/events?limit=1");
  expect(events[0].operation).toBe("object.create");
});
